def _stringify_custom_synthesis_answer(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, (str, int, float, bool)):
        return str(value)
    if isinstance(value, list):
        return "\n".join(
            item
            for item in (
                _stringify_custom_synthesis_answer(candidate).strip()
                for candidate in value
            )
            if item
        )
    if isinstance(value, dict):
        parts: list[str] = []
        for key, label in (
            ("position", "Answer"),
            ("value", "Answer"),
            ("answer", "Answer"),
            ("selected", "Selected"),
            ("selectedScore", "Score"),
            ("score", "Score"),
            ("evidence", "Evidence"),
            ("confidence", "Confidence"),
            ("confidenceJustification", "Confidence rationale"),
            ("counterarguments", "Counterarguments"),
        ):
            if key not in value:
                continue
            text = _stringify_custom_synthesis_answer(value.get(key)).strip()
            if text:
                parts.append(f"{label}: {text}")
        if parts:
            return "\n".join(parts)
        try:
            return json.dumps(value, ensure_ascii=False, indent=2)
        except TypeError:
            return str(value)
    return str(value)

functions._question_label_for_custom_synthesis:
def _question_label_for_custom_synthesis(question: Any, fallback: str) -> str:
    if isinstance(question, str):
        return question.strip() or fallback
    if isinstance(question, dict):
        for key in ("label", "text", "question", "title"):
            value = question.get(key)
            if isinstance(value, str) and value.strip():
                return ((str(question.get("sectionTitle") or "").strip() + " — ") if question.get("sectionTitle") else "") + value.strip()
    return fallback

