def _format_custom_synthesis_material(
    questions: list[Any],
    response_dicts: list[dict[str, Any]],
) -> str:
    labels = [
        _question_label_for_custom_synthesis(question, f"Question {index + 1}")
        for index, question in enumerate(questions)
    ]
    lines: list[str] = ["Questions:"]
    for index, label in enumerate(labels, start=1):
        lines.append(f"{index}. {label}")
    lines.append("")
    lines.append("Responses:")
    for response_index, response in enumerate(response_dicts, start=1):
        lines.append("")
        lines.append(f"Response {response_index} ({response.get('email') or f'Expert {response_index}'}):")
        answers = response.get("answers") or {}
        if isinstance(answers, str):
            try:
                answers = json.loads(answers)
            except json.JSONDecodeError:
                answers = {}
        if not isinstance(answers, dict):
            answers = {}
        for question_index, label in enumerate(labels, start=1):
            answer = _stringify_custom_synthesis_answer(
                answers.get(f"q{question_index}")
            ).strip()
            lines.append(f"Q{question_index}. {label}")
            lines.append(f"A: {answer or 'No answer'}")
    return "\n".join(lines)

functions._format_custom_claim_list:
def _format_custom_claim_list(
    markdown: str,
    questions: list[Any] | None = None,
    response_dicts: list[dict[str, Any]] | None = None,
) -> str:
    """Render custom claim bullets as simple HTML so line breaks are preserved."""
    def status_style(status: str) -> tuple[str, str, str, str]:
        normalised = status.strip().lower()
        if "clear" in normalised and "disagreement" in normalised:
            return ("#dc2626", "#fef2f2", "Clear disagreement", "🟥")
        if "question" in normalised or "mixed" in normalised or "uncertain" in normalised:
            return ("#d97706", "#fffbeb", "Questionable", "🟨")
        return ("#16a34a", "#f0fdf4", "Uncontested", "🟩")

    def normalise_statement(value: str) -> str:
        return re.sub(r"^[-*+]\s*", "", value).strip()

    def is_likert_only_statement(value: str) -> bool:
        text = normalise_statement(value)
        text = re.sub(r"^response\s+[^:]+\s*:\s*", "", text, flags=re.IGNORECASE)
        text = text.strip().strip('"“”').lower()
        likert_values = {
            "strongly agree",
            "agree",
            "neither agree nor disagree",
            "neither agree or disagree",
            "disagree",
            "strongly disagree",
            "don't know",
            "dont know",
            "unsure",
            "not sure",
        }
        return text in likert_values or bool(re.fullmatch(r"\d+(?:\.\d+)?", text))

    def has_statement_values(values: list[str]) -> bool:
        return any(
            value.strip()
            and value.strip().lower() not in {"none", "n/a", "not applicable", "no opposing statements"}
            and not is_likert_only_statement(value)
            for value in values
        )

    def render_statement_details(title: str, statements: list[str]) -> str:
        filtered = [
            normalise_statement(statement)
            for statement in statements
            if normalise_statement(statement).lower() not in {"none", "n/a", "not applicable", "no opposing statements"}
            and not is_likert_only_statement(statement)
        ]
        if not filtered:
            return ""
        output = [f"<details><summary>{html.escape(title)}</summary>", "<ul>"]
        for statement in dict.fromkeys(filtered):
            output.append(f"<li>{html.escape(statement)}</li>")
        output.extend(["</ul>", "</details>"])
        return "\n".join(output)

    def render_expert_details(title: str, experts: list[str]) -> str:
        filtered = [
            normalise_statement(expert)
            for expert in experts
            if normalise_statement(expert).lower() not in {"none", "n/a", "not applicable"}
        ]
        if not filtered:
            return ""
        output = [f"<details><summary>{html.escape(title)}</summary>", "<ul>"]
        for expert in dict.fromkeys(filtered):
            output.append(f"<li>{html.escape(expert)}</li>")
        output.extend(["</ul>", "</details>"])
        return "\n".join(output)

    def enrich_expert_positions(claims: list[dict[str, Any]]) -> None:
        if not questions or not response_dicts:
            return

        stop_words = {
            "a", "an", "and", "are", "be", "can", "for", "if", "in", "is",
            "of", "on", "or", "the", "to", "with",
        }

        def tokens(value: str) -> set[str]:
            return {
                token
                for token in re.findall(r"[a-z0-9]+", value.lower())
                if token not in stop_words
            }

        question_labels = [
            _question_label_for_custom_synthesis(question, f"Question {index + 1}")
            for index, question in enumerate(questions)
        ]
        question_tokens = [tokens(label) for label in question_labels]
        supportive = {"strongly agree", "agree", "yes", "support", "supported", "true"}
        opposing = {"strongly disagree", "disagree", "no", "oppose", "opposed", "false"}
        uncertain = {
            "neither agree nor disagree", "neither agree or disagree", "unsure",
            "not sure", "don't know", "dont know", "unable to judge — need more information",
        }

        for claim in claims:
            claim_tokens = tokens(claim.get("text", ""))
            if not claim_tokens:
                continue
            scores = [
                len(claim_tokens & candidate) / max(1, len(claim_tokens))
                for candidate in question_tokens
            ]
            question_index = max(range(len(scores)), key=scores.__getitem__)
            if scores[question_index] < 0.35:
                continue

            positions: list[tuple[str, str]] = []
            recognised = 0
            for response_index, response in enumerate(response_dicts, start=1):
                answers = response.get("answers") or {}
                if isinstance(answers, str):
                    try:
                        answers = json.loads(answers)
                    except json.JSONDecodeError:
                        answers = {}
                if not isinstance(answers, dict):
                    answers = {}
                raw_answer = _stringify_custom_synthesis_answer(
                    answers.get(f"q{question_index + 1}")
                ).strip()
                first_line = (raw_answer.splitlines() or ["No answer"])[0].strip()
                answer = re.sub(
                    r"^(?:answer|selected)\s*:\s*",
                    "",
                    first_line,
                    flags=re.IGNORECASE,
                ).strip() or "No answer"
                normalised = answer.lower()
                if normalised in supportive:
                    group = "supporting_experts"
                    recognised += 1
                elif normalised in opposing:
                    group = "opposing_experts"
                    recognised += 1
                elif normalised in uncertain:
                    group = "uncertain_experts"
                    recognised += 1
                else:
                    continue
                expert_label = response.get("email") or f"Expert {response_index}"
                positions.append(
                    (
                        group,
                        f"Response {response_index} ({expert_label}): {answer}",
                    )
                )

            if recognised < max(2, len(positions) // 2):
                continue
            claim["_recorded_positions"] = True
            claim["supporting_experts"] = []
            claim["opposing_experts"] = []
            claim["uncertain_experts"] = []
            for group, position in positions:
                claim[group].append(position)
            claim["people"] = (
                f"{len(claim['supporting_experts'])} of {len(positions)}"
            )

    def complete_written_evidence(claims: list[dict[str, Any]]) -> None:
        from core.claim_grounding import ground_claim
        if not response_dicts:
            return
        sources, labels = [], []
        for index, response in enumerate(response_dicts, start=1):
            answers = response.get("answers") or {}
            if isinstance(answers, str):
                try:
                    answers = json.loads(answers)
                except json.JSONDecodeError:
                    answers = {}
            sources.append([_stringify_custom_synthesis_answer(value) for value in answers.values()] if isinstance(answers, dict) else [])
            labels.append(response.get("email") or f"Expert {index}")
        for claim in claims:
            ground_claim(claim, sources, labels)

    def render_structured_claims(claims: list[dict[str, Any]]) -> str:
        output = ["<h2>Claims</h2>"]
        for index, item in enumerate(claims, start=1):
            colour, background, _label, marker = status_style(item.get("status", "Questionable"))
            claim_text = html.escape(item.get("text", "").strip())
            people = html.escape(item.get("people", "").strip() or "Not counted")
            opposing = item.get("opposing", "").strip()
            supporting_experts = item.get("supporting_experts", [])
            opposing_experts = item.get("opposing_experts", [])
            uncertain_experts = item.get("uncertain_experts", [])
            supporting_statements = item.get("supporting_statements", [])
            opposing_statements = item.get("opposing_statements", [])
            uncertain_statements = item.get("uncertain_statements", [])
            if index > 1:
                output.append("<p>&nbsp;</p>")
                output.append("<hr>")
                output.append("<p>&nbsp;</p>")
            output.append(
                "<div "
                f'style="margin: 0 0 1.15rem 0; padding: 0.95rem 1rem; '
                f'border-left: 5px solid {colour}; background: {background}; '
                'border-radius: 0.45rem;">'
            )
            output.append(f"<p>{marker} Claim {index}: <strong>{claim_text}</strong></p>")
            output.append(f"<p>People making this claim: <strong>{people}</strong></p>")
            for title, experts in (
                ("Show supporting experts", supporting_experts),
                ("Show opposing experts", opposing_experts),
                ("Show uncertain experts", uncertain_experts),
            ):
                expert_details = render_expert_details(title, experts)
                if expert_details:
                    output.append(expert_details)
            supporting_details = render_statement_details("Show supporting statements", supporting_statements)
            if supporting_details:
                output.append(supporting_details)
            if has_statement_values(opposing_statements):
                opposing_details = render_statement_details("Show opposing statements", opposing_statements)
                if opposing_details:
                    output.append(opposing_details)
            if has_statement_values(uncertain_statements):
                uncertain_details = render_statement_details("Show uncertain statements", uncertain_statements)
                if uncertain_details:
                    output.append(uncertain_details)
            output.append("</div>")
        return "\n".join(output)

    structured_claims: list[dict[str, Any]] = []
    current_claim: dict[str, Any] | None = None
    current_statement_key: str | None = None
    for raw_line in markdown.splitlines():
        stripped = raw_line.strip()
        if not stripped:
            continue
        if re.match(r"^claim\s+\d+\b", stripped, re.IGNORECASE):
            if current_claim and current_claim.get("text"):
                structured_claims.append(current_claim)
            current_claim = {
                "status": "Questionable",
                "people": "",
                "text": "",
                "opposing": "",
                "supporting_experts": [],
                "opposing_experts": [],
                "uncertain_experts": [],
                "supporting_statements": [],
                "opposing_statements": [],
                "uncertain_statements": [],
            }
            current_statement_key = None
            inline_text = re.sub(r"^claim\s+\d+\s*[:\-–—]?\s*", "", stripped, flags=re.IGNORECASE).strip()
            if inline_text:
                current_claim["text"] = inline_text
            continue
        if current_claim is None:
            continue
        match = re.match(r"^(status|people|text|opposing views?|supporting experts?|opposing experts?|uncertain experts?|supporting statements?|opposing statements?|uncertain statements?)\s*:\s*(.*)$", stripped, re.IGNORECASE)
        if not match:
            if current_statement_key and re.match(r"^[-*+]\s+", stripped):
                current_claim[current_statement_key].append(normalise_statement(stripped))
            elif current_statement_key and current_claim[current_statement_key]:
                current_claim[current_statement_key][-1] = f"{current_claim[current_statement_key][-1]} {stripped}".strip()
            elif current_claim.get("text"):
                current_claim["text"] = f"{current_claim['text']} {stripped}".strip()
            continue
        key = match.group(1).lower()
        value = match.group(2).strip()
        current_statement_key = None
        if key == "status":
            current_claim["status"] = value
        elif key == "people":
            current_claim["people"] = value
        elif key == "text":
            current_claim["text"] = value
        elif key.startswith("opposing view"):
            current_claim["opposing"] = value
        elif key.startswith("supporting expert"):
            current_statement_key = "supporting_experts"
            if value:
                current_claim[current_statement_key].append(normalise_statement(value))
        elif key.startswith("opposing expert"):
            current_statement_key = "opposing_experts"
            if value:
                current_claim[current_statement_key].append(normalise_statement(value))
        elif key.startswith("uncertain expert"):
            current_statement_key = "uncertain_experts"
            if value:
                current_claim[current_statement_key].append(normalise_statement(value))
        elif key.startswith("supporting statement"):
            current_statement_key = "supporting_statements"
            if value:
                current_claim[current_statement_key].append(normalise_statement(value))
        elif key.startswith("opposing statement"):
            current_statement_key = "opposing_statements"
            if value:
                current_claim[current_statement_key].append(normalise_statement(value))
        else:
            current_statement_key = "uncertain_statements"
            if value:
                current_claim[current_statement_key].append(normalise_statement(value))
    if current_claim and current_claim.get("text"):
        structured_claims.append(current_claim)

    if structured_claims:
        enrich_expert_positions(structured_claims)
        complete_written_evidence(structured_claims)
        seen_structured: set[str] = set()
        deduped_structured: list[dict[str, Any]] = []
        for item in structured_claims:
            claim_key = re.sub(r"\s+", " ", item.get("text", "").strip().lower())
            if not claim_key or claim_key in seen_structured:
                continue
            seen_structured.add(claim_key)
            deduped_structured.append(item)
        return render_structured_claims(deduped_structured[:12])

    section_order = [
        "### Agreement claims",
        "### Disagreement claims",
        "### Uncertain or conditional claims",
        "### Isolated claims",
    ]
    sections: dict[str, list[tuple[str, str]]] = {heading: [] for heading in section_order}
    seen: set[str] = set()
    current_section: str | None = None
    pending_claim: str | None = None
    pending_confidence = "Medium"

    def normalise_heading(value: str) -> str | None:
        heading = value.lstrip("#").strip().lower()
        if "disagreement" in heading or "contested" in heading or "conflict" in heading:
            return "### Disagreement claims"
        if "uncertain" in heading or "conditional" in heading or "mixed" in heading:
            return "### Uncertain or conditional claims"
        if "isolated" in heading or "minority" in heading:
            return "### Isolated claims"
        if "agreement" in heading or "consensus" in heading or "supported" in heading:
            return "### Agreement claims"
        return None

    def flush_pending() -> None:
        nonlocal pending_claim, pending_confidence
        if not current_section or pending_claim is None:
            pending_claim = None
            pending_confidence = "Medium"
            return
        claim = pending_claim.strip().rstrip(".")
        if claim:
            claim = f"{claim}."
        claim_key = re.sub(r"\s+", " ", claim.lower())
        if claim and claim_key not in seen:
            seen.add(claim_key)
            sections[current_section].append((claim, pending_confidence))
        pending_claim = None
        pending_confidence = "Medium"

    for line in markdown.splitlines():
        stripped = line.strip()
        if stripped.startswith("#"):
            flush_pending()
            current_section = normalise_heading(stripped) or current_section
            continue
        plain_heading = normalise_heading(stripped)
        if plain_heading and not stripped.startswith("-"):
            flush_pending()
            current_section = plain_heading
            continue

        if not current_section:
            if "claim" in stripped.lower():
                current_section = "### Uncertain or conditional claims"
            else:
                continue

        if stripped.startswith("- **Claim:**"):
            flush_pending()
            pending_claim = stripped.removeprefix("- **Claim:**").strip()
            continue
        if stripped.startswith("- **Claim**"):
            flush_pending()
            pending_claim = stripped.removeprefix("- **Claim**").strip()
            continue
        bold_bullet_match = re.match(r"-\s+\*\*(.+?)\*\*\s*$", stripped)
        if bold_bullet_match and not bold_bullet_match.group(1).lower().startswith("confidence:"):
            flush_pending()
            pending_claim = bold_bullet_match.group(1).strip()
            continue
        if stripped.startswith("- Claim:"):
            flush_pending()
            pending_claim = stripped.removeprefix("- Claim:").strip()
            continue
        generic_bullet_match = re.match(r"[-*+]\s+(.+)$", stripped)
        if generic_bullet_match and not generic_bullet_match.group(1).lower().startswith("confidence:"):
            flush_pending()
            pending_claim = generic_bullet_match.group(1).strip()
            continue
        if stripped.startswith("Claim:"):
            flush_pending()
            pending_claim = stripped.removeprefix("Claim:").strip()
            continue
        if stripped.startswith("**Confidence:**"):
            pending_confidence = stripped.removeprefix("**Confidence:**").strip() or "Medium"
            continue
        if stripped.startswith("- **Confidence:**"):
            pending_confidence = stripped.removeprefix("- **Confidence:**").strip() or "Medium"
            continue
        if stripped.startswith("Confidence:"):
            pending_confidence = stripped.removeprefix("Confidence:").strip() or "Medium"
            continue
        if stripped.startswith("- Confidence:"):
            pending_confidence = stripped.removeprefix("- Confidence:").strip() or "Medium"
            continue
        if pending_claim is not None and stripped and not stripped.startswith("#"):
            pending_claim = f"{pending_claim} {stripped}".strip()

    flush_pending()

    output: list[str] = ["<h2>Claims</h2>"]
    for heading in section_order:
        claims = sections.get(heading) or []
        if not claims:
            continue
        section_title = heading.removeprefix("### ").strip()
        output.append(f"<h3>{html.escape(section_title)}</h3>")
        output.append("<ul>")
        for claim, confidence in claims:
            output.append(
                "<li>"
                f"{html.escape(claim)}"
                "<br>"
                f"<strong>Confidence:</strong> {html.escape(confidence)}"
                "</li>"
            )
        output.append("</ul>")

    formatted = "\n".join(output).strip()
    return formatted if any(sections.get(heading) for heading in section_order) else markdown.strip()

